-- Built-in food catalog: common foods worldwide with a strong Egyptian section.
--
-- Values are per serving (serving_g grams). Single ingredients follow USDA
-- FoodData Central (public domain). Composite dishes (most of the Egyptian
-- section) are computed by the project from standard home recipes, summing the
-- ingredients for a typical serving (MIT, like the rest of the repo).
-- Invariant (enforced by a unit test in api/src/food/catalog.rs):
-- kcal is within 10% (or 10 kcal) of 4*protein + 4*carbs + 9*fat, serving_g > 0.
--
-- This file is generated; keep one row per line so the test can parse it.

-- Allow source = 'builtin'. The original CHECKs were unnamed, so drop every
-- CHECK on foods that mentions `source` (whatever Postgres named them) and
-- re-add them with explicit names.
DO $$
DECLARE
    c record;
BEGIN
    FOR c IN
        SELECT conname FROM pg_constraint
        WHERE conrelid = 'foods'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid) LIKE '%source%'
    LOOP
        EXECUTE format('ALTER TABLE foods DROP CONSTRAINT %I', c.conname);
    END LOOP;
END $$;

ALTER TABLE foods
    ADD CONSTRAINT foods_source_check
        CHECK (source IN ('usda', 'off', 'custom', 'builtin')),
    ADD CONSTRAINT foods_custom_owner_check
        CHECK ((source = 'custom') = (owner_id IS NOT NULL));

ALTER TABLE foods
    ADD COLUMN category text,
    ADD COLUMN name_ar  text;

CREATE INDEX foods_builtin_category_idx ON foods (category, name) WHERE source = 'builtin';

